var catalog_name = apim.getvariable('env.path');
var file_path = 'local:///policy/common/'+catalog_name+'/CreateEIEHeader_v3.2.js';
var eieheader_module = require(file_path);
eieheader_module.create_eie_header_v3_2('header','v3.2','JSON','');

var respJson = apim.getvariable('message.body');
var host_name = apim.getvariable('api.endpoint.hostname');
var org_name = apim.getvariable('api.org.name');
var catalogName = apim.getvariable('env.path');
var resoursePath = apim.getvariable('request.path');
var chunk_link = respJson.link;
var chunk_entry = respJson.entry;
var req_query_params = apim.getvariable('request.search');
var finalFullUrl;
var apic_req_url = "https://" + host_name + "/" + org_name + "/" + catalogName + resoursePath;
if(catalogName=="prod" || catalogName=="prod2")
{
	var apic_req_url = "https://" + host_name + "/" + org_name  + resoursePath;
}

if(apim.getvariable('request.parameters.id')!=undefined){
	var temp= '/'+apim.getvariable('request.parameters.id');
	console.error("IndexofTEMP::"+apic_req_url.indexOf(temp));
	if(apic_req_url.indexOf(temp)!= -1)
	{
		apic_req_url=apic_req_url.substring(0,apic_req_url.indexOf(temp));
	}
	
}
var array_apic_url = apic_req_url.split('/');
var apic_url_length = array_apic_url.length;

var apic_popped = array_apic_url[apic_url_length - 1];
var full_final_split_1;

if (respJson.entry != undefined || respJson.link != undefined) {
   if(respJson.link !=undefined)
       {
   for (var i = 0; i < chunk_link.length; i++) {
      var split_url = chunk_link[i].url.split('?');
      var x = split_url[0].split('/');
      var y = x.length;
      var resp_popped = x[y - 1]; //path parameter of backend response from url
	  var resp_popped_split =resp_popped;
	  if(resp_popped.indexOf('?')!=-1)
	  {
		resp_popped_split =resp_popped.substring(0,resp_popped.indexOf('?'));
	  }
      if (apic_popped == resp_popped_split) //To confirm whether backend has path param or not
      {
         if (split_url[1] == undefined || split_url[1] == "") //To check if backend resp has query param or not
         {
            finalFullUrl = apic_req_url;
         } else {
            finalFullUrl = apic_req_url + '?' + split_url[1];
         }
         respJson.link[i].url = finalFullUrl;

      } else
      {
         if (split_url[1] == undefined || split_url[1] == "") {
            finalFullUrl = apic_req_url + "/" + resp_popped;
			finalFullUrl = finalFullUrl.replace('/?','');
         } else {
            finalFullUrl = apic_req_url + "/" + resp_popped;
			finalFullUrl = finalFullUrl.replace('/?','?');
         }
         respJson.link[i].url = finalFullUrl;
      }
   }
}
   if (respJson.entry != undefined) {
      for (var i = 0; i < chunk_entry.length; i++) {
          if(chunk_entry[i].fullUrl!=undefined && chunk_entry[i].resource.resourceType !="Provenance" )
          {
         var split_url = chunk_entry[i].fullUrl.split('?');
         var x = split_url[0].split('/');
         var y = x.length;
         var resp_popped = x[y - 1]; //path parameter of backend response
		 var resp_popped_split =resp_popped;
		if(resp_popped.indexOf('?')!=-1)
		  {
			resp_popped_split =resp_popped.substring(0,resp_popped.indexOf('?'));
		  }
			 
         if (apic_popped == resp_popped_split) //this is to confirm whether backend has path param or not
         {
            if (split_url[1] == undefined || split_url[1] == "") //this block is to check if backend resp has query param or not
            {
               finalFullUrl = apic_req_url;
            } else {
               finalFullUrl = apic_req_url + '?' + split_url[1];
            }
            respJson.entry[i].fullUrl = finalFullUrl;

         } else
         {
            if (split_url[1] == undefined || split_url[1] == "") {
               finalFullUrl = apic_req_url + "/" + resp_popped;
			   finalFullUrl = finalFullUrl.replace('/?','');
            } else {
               finalFullUrl = apic_req_url + "/" + resp_popped;
			   finalFullUrl = finalFullUrl.replace('/?','?');
            }
            respJson.entry[i].fullUrl = finalFullUrl;
			
         }
      }else{
		  if(respJson.entry[i].fullUrl!=undefined){
			respJson.entry[i].fullUrl = respJson.entry[i].resource.id;
		  }
		  
	  }
      }
   }
   session.output.write(respJson);
   apim.output('application/fhir+json');
} else {
   session.output.write(apim.getvariable('message.body'));
   apim.output('application/fhir+json');
}
